structured_sop_json:
{
  "steps": [
    {
      "name": "Collect Written Consent and New Mobile Number from Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Customer requests mobile number change in policy",
      "sub_steps": [
        {
          "id": "1.1",
          "action": "Request customer to send written consent from registered email ID",
          "required": "Yes (Mandatory)",
          "validation": "Verify email is received from registered email ID",
          "note": "Consent must be in writing and sent from the email registered with the policy",
          "on_error": "Follow up with customer and request again"
        },
        {
          "id": "1.2",
          "action": "Request customer to provide new mobile number details",
          "required": "Yes (Mandatory)",
          "validation": "Verify new mobile number is provided and matches customer records",
          "note": "Ensure the new mobile number is clearly mentioned in the email",
          "on_error": "Follow up with customer and request again"
        }
      ],
      "decisions": [
        {
          "when": "1.1 = false",
          "action": "Remind customer to send written consent from registered email ID",
          "status": null
        },
        {
          "when": "1.2 = false",
          "action": "Remind customer to provide new mobile number details",
          "status": null
        },
        {
          "when": "1.1 = true AND 1.2 = true",
          "action": "Proceed to STEP_2",
          "status": null
        }
      ]
    },
    {
      "name": "Raise Endorsement Request and Process Instant Endorsement",
      "actor": "Advisor",
      "to": "System (Endorsement Module)",
      "trigger": "Written consent and new mobile number received from customer",
      "sub_steps": [
        {
          "id": "2.1",
          "action": "Raise a ticket through the endorsement module",
          "required": "Yes (Mandatory)",
          "validation": "Confirm ticket is created in the endorsement module",
          "note": "Use Care's endorsement module; select correct sub-issue type",
          "on_error": "Retry ticket creation or escalate to technical support"
        },
        {
          "id": "2.2",
          "action": "Process instant endorsement using Care API (if services are live)",
          "required": "Conditional",
          "validation": "Verify instant endorsement is processed and status is updated in system",
          "note": "If Care API services are not live, follow manual process as per insurer guidelines",
          "on_error": "If API fails, follow manual process or escalate to insurer"
        }
      ],
      "decisions": [
        {
          "when": "2.1 = false",
          "action": "Retry or escalate ticket creation issue",
          "status": null
        },
        {
          "when": "2.2 = false AND Care API services are live",
          "action": "Retry endorsement processing or escalate to insurer",
          "status": null
        },
        {
          "when": "2.1 = true AND (2.2 = true OR Care API services not live)",
          "action": "Proceed to STEP_3",
          "status": null
        }
      ]
    },
    {
      "name": "Share Endorsement Letter (EL) with Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Endorsement processed and EL generated in real time by Care",
      "sub_steps": [
        {
          "id": "3.1",
          "action": "Download the generated Endorsement Letter (EL) from the system",
          "required": "Yes (Mandatory)",
          "validation": "Confirm EL is available and downloaded",
          "note": "EL is generated in real time in Care system",
          "on_error": "Retry download or contact technical support"
        },
        {
          "id": "3.2",
          "action": "Share the Endorsement Letter (EL) with the customer",
          "required": "Yes (Mandatory)",
          "validation": "Confirm customer has received the EL",
          "note": "Send via email or preferred communication channel",
          "on_error": "Resend EL or contact customer for alternate delivery method"
        }
      ],
      "decisions": [
        {
          "when": "3.1 = false",
          "action": "Retry download or escalate to technical support",
          "status": null
        },
        {
          "when": "3.2 = false",
          "action": "Resend EL or contact customer for alternate delivery method",
          "status": null
        },
        {
          "when": "3.1 = true AND 3.2 = true",
          "action": "STATUS: COMPLETED",
          "status": "COMPLETED"
        }
      ]
    }
  ]
}

{
  "steps": [
    {
      "name": "Collect Written Consent and Required Documents from Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Customer requests change in communication address for Care policy",
      "sub_steps": [
        {
          "id": "1.1",
          "action": "Request customer to share written consent from registered email ID",
          "required": "Yes (Mandatory)",
          "validation": "Verify written consent is received from registered email ID",
          "note": "Consent must be from the email ID registered with the insurer",
          "on_error": "Follow up with customer and request again"
        },
        {
          "id": "1.2",
          "action": "Request customer to provide details to be changed",
          "required": "Yes (Mandatory)",
          "validation": "Confirm all required details for address change are provided",
          "note": "Details should match the policy records for identification",
          "on_error": "Ask customer to provide missing details"
        },
        {
          "id": "1.3",
          "action": "Request customer to provide government ID proof",
          "required": "Yes (Mandatory)",
          "validation": "Verify government ID proof is received and matches customer identity",
          "note": "Acceptable ID proofs: Aadhaar, Passport, Voter ID, etc.",
          "on_error": "Request customer to resend valid ID proof"
        }
      ],
      "decisions": [
        {
          "when": "1.1 = false",
          "action": "Follow up with customer for written consent",
          "status": null
        },
        {
          "when": "1.2 = false",
          "action": "Request customer to provide required details",
          "status": null
        },
        {
          "when": "1.3 = false",
          "action": "Request customer to provide valid government ID proof",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_2",
          "status": null
        }
      ]
    },
    {
      "name": "Raise Endorsement Request and Process Instant Endorsement",
      "actor": "Advisor",
      "to": "System (Care Endorsement Module)",
      "trigger": "All required documents and consent received from customer",
      "sub_steps": [
        {
          "id": "2.1",
          "action": "Raise a ticket through the endorsement module",
          "required": "Yes (Mandatory)",
          "validation": "Confirm ticket is successfully raised in the system",
          "note": "Use Care's endorsement module; ensure correct policy details are entered",
          "on_error": "Retry ticket creation or escalate to technical support"
        },
        {
          "id": "2.2",
          "action": "Process instant endorsement via Care API services",
          "required": "Yes (Mandatory)",
          "validation": "Verify endorsement is processed and status is updated in real time",
          "note": "Care API services are live for instant processing",
          "on_error": "Retry endorsement process or escalate to insurer support"
        }
      ],
      "decisions": [
        {
          "when": "2.1 = false",
          "action": "Retry or escalate ticket creation issue",
          "status": null
        },
        {
          "when": "2.2 = false",
          "action": "Retry endorsement process or escalate to insurer",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_3",
          "status": null
        }
      ]
    },
    {
      "name": "Share Endorsement Letter (EL) with Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Endorsement is processed and EL is generated in real time by Care",
      "sub_steps": [
        {
          "id": "3.1",
          "action": "Download or retrieve the Endorsement Letter (EL) from the system",
          "required": "Yes (Mandatory)",
          "validation": "Confirm EL is available and correct for the policy",
          "note": "EL is generated in real time by Care system",
          "on_error": "Check system for EL generation status or contact insurer"
        },
        {
          "id": "3.2",
          "action": "Share the Endorsement Letter (EL) with the customer",
          "required": "Yes (Mandatory)",
          "validation": "Confirm customer has received the EL",
          "note": "Send via registered email or preferred communication channel",
          "on_error": "Resend EL or contact customer for alternate delivery method"
        }
      ],
      "decisions": [
        {
          "when": "3.1 = false",
          "action": "Check system or escalate to insurer for EL generation",
          "status": null
        },
        {
          "when": "3.2 = false",
          "action": "Resend EL or contact customer for alternate delivery method",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "STATUS: COMPLETED",
          "status": "COMPLETED"
        }
      ]
    }
  ]
}

{
  "steps": [
    {
      "name": "Collect Disease Details and Medical Documents from Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Customer requests PED addition or advisor initiates PED addition process",
      "sub_steps": [
        {
          "id": "1.1",
          "action": "Send email to customer asking which disease they want to add",
          "required": "Yes (Mandatory)",
          "validation": "Verify email sent to customer's registered email ID",
          "note": "Ensure email is sent to the customer's registered email ID",
          "on_error": "Resend email or follow up with customer"
        },
        {
          "id": "1.2",
          "action": "Request customer to share related medical documents (FCP, Medical History Paper, Lab Test Reports, Latest Prescription if applicable)",
          "required": "Yes (Mandatory)",
          "validation": "Verify all required documents are received",
          "note": "Collect all mandatory documents in advance",
          "on_error": "Follow up with customer for missing documents"
        },
        {
          "id": "1.3",
          "action": "Request customer to provide written consent from their registered email ID",
          "required": "Yes (Mandatory)",
          "validation": "Verify consent received from registered email ID",
          "note": "Consent must mention exact diagnosis and disease history in email body",
          "on_error": "Request customer to resend consent with required details"
        },
        {
          "id": "1.4",
          "action": "Verify that customer has mentioned exact diagnosis and disease history in the email body",
          "required": "Yes (Mandatory)",
          "validation": "Check email content for diagnosis and disease history",
          "note": "Do not proceed without complete information",
          "on_error": "Ask customer to update email with required details"
        }
      ],
      "decisions": [
        {
          "when": "1.1 = false or 1.2 = false or 1.3 = false or 1.4 = false",
          "action": "Follow up with customer for missing information or documents",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_2",
          "status": null
        }
      ]
    },
    {
      "name": "Raise Endorsement Request and Send to Insurer",
      "actor": "Advisor",
      "to": "Insurer (via System)",
      "trigger": "All required documents and consent received from customer",
      "sub_steps": [
        {
          "id": "2.1",
          "action": "Raise PED addition request through endorsement module",
          "required": "Yes (Mandatory)",
          "validation": "Verify request is logged in the system",
          "note": "Use insurer's endorsement module",
          "on_error": "Retry submission or escalate to technical support"
        },
        {
          "id": "2.2",
          "action": "Attach all collected documents to the request",
          "required": "Yes (Mandatory)",
          "validation": "Check all mandatory documents are attached",
          "note": "Ensure no document is missing",
          "on_error": "Attach missing documents and resubmit"
        },
        {
          "id": "2.3",
          "action": "Submit the request to the insurer",
          "required": "Yes (Mandatory)",
          "validation": "Confirm submission acknowledgment from insurer/system",
          "note": "Keep submission confirmation for records",
          "on_error": "Resubmit or contact insurer support"
        }
      ],
      "decisions": [
        {
          "when": "2.1 = false or 2.2 = false or 2.3 = false",
          "action": "Review and correct errors, then retry submission",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_3",
          "status": null
        }
      ]
    },
    {
      "name": "Handle Additional Document Requests from Insurer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Insurer requests additional medical documents",
      "sub_steps": [
        {
          "id": "3.1",
          "action": "Inform customer about additional documents required by insurer",
          "required": "Conditional",
          "validation": "Verify customer is notified",
          "note": "Specify exactly which documents are needed",
          "on_error": "Follow up with customer"
        },
        {
          "id": "3.2",
          "action": "Collect additional documents from customer",
          "required": "Conditional",
          "validation": "Verify receipt of requested documents",
          "note": "Check for completeness and clarity",
          "on_error": "Request again or escalate if not received"
        },
        {
          "id": "3.3",
          "action": "Confirm all additional documents are received and complete",
          "required": "Conditional",
          "validation": "Check all insurer-requested documents are present",
          "note": "Do not proceed until all documents are received",
          "on_error": "Follow up with customer"
        }
      ],
      "decisions": [
        {
          "when": "3.1 = false or 3.2 = false or 3.3 = false (if insurer requests additional docs)",
          "action": "Continue following up with customer until all documents are received",
          "status": null
        },
        {
          "when": "All sub-steps complete or no additional documents requested",
          "action": "Proceed to STEP_4",
          "status": null
        }
      ]
    },
    {
      "name": "Send Documents to Insurer for Underwriting Decision",
      "actor": "Advisor",
      "to": "Insurer",
      "trigger": "All required and additional documents collected",
      "sub_steps": [
        {
          "id": "4.1",
          "action": "Send all collected documents to insurer",
          "required": "Yes (Mandatory)",
          "validation": "Verify documents sent and acknowledged by insurer",
          "note": "Include any newly received documents",
          "on_error": "Resend documents or contact insurer"
        },
        {
          "id": "4.2",
          "action": "Confirm insurer's underwriting team has received documents",
          "required": "Yes (Mandatory)",
          "validation": "Obtain confirmation from insurer",
          "note": "Follow up if no acknowledgment received",
          "on_error": "Follow up with insurer"
        }
      ],
      "decisions": [
        {
          "when": "4.1 = false or 4.2 = false",
          "action": "Resend documents or follow up with insurer",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_5",
          "status": null
        }
      ]
    },
    {
      "name": "Share Endorsement TAT with Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Request submitted to insurer and documents sent",
      "sub_steps": [
        {
          "id": "5.1",
          "action": "Inform customer of standard endorsement TAT (7-10 working days)",
          "required": "Yes (Mandatory)",
          "validation": "Verify customer is notified via email or preferred channel",
          "note": "Set customer expectations for processing time",
          "on_error": "Resend TAT information or follow up with customer"
        }
      ],
      "decisions": [
        {
          "when": "5.1 = false",
          "action": "Resend TAT information to customer",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_6",
          "status": null
        }
      ]
    },
    {
      "name": "Validate and Share Endorsed Letter/Updated Policy Copy with Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Insurer shares Endorsed Letter or updated Policy Copy",
      "sub_steps": [
        {
          "id": "6.1",
          "action": "Validate the received Endorsed Letter or updated Policy Copy for accuracy and completeness",
          "required": "Yes (Mandatory)",
          "validation": "Check document details match requested PED addition and customer information",
          "note": "Ensure no errors or omissions in the document",
          "on_error": "Contact insurer for corrections"
        },
        {
          "id": "6.2",
          "action": "Share the validated document with the customer",
          "required": "Yes (Mandatory)",
          "validation": "Confirm customer has received the document",
          "note": "Send via customer's registered email ID",
          "on_error": "Resend document or follow up with customer"
        },
        {
          "id": "6.3",
          "action": "Close the ticket in the system",
          "required": "Yes (Mandatory)",
          "validation": "Verify ticket status is updated to closed",
          "note": "Ensure all customer queries are resolved before closure",
          "on_error": "Update ticket status and notify customer if needed"
        }
      ],
      "decisions": [
        {
          "when": "6.1 = false",
          "action": "Contact insurer for corrections before proceeding",
          "status": null
        },
        {
          "when": "6.2 = false",
          "action": "Resend document or follow up with customer",
          "status": null
        },
        {
          "when": "6.3 = false",
          "action": "Update ticket status and ensure closure",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "STATUS: COMPLETED",
          "status": "COMPLETED"
        }
      ]
    }
  ]
}

