{
  "steps": [
    {
      "name": "Collect Customer Consent and Required Documents",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Customer requests change in Sum Insured details",
      "sub_steps": [
        {
          "id": "1.1",
          "action": "Request customer to share written consent from registered email ID",
          "required": "Yes (Mandatory)",
          "validation": "Verify written consent is received from registered email ID",
          "note": "Consent must be from the email registered with the policy",
          "on_error": "Follow up with customer; explain requirement"
        },
        {
          "id": "1.2",
          "action": "Request customer to share details to be changed",
          "required": "Yes (Mandatory)",
          "validation": "Confirm all required change details are provided",
          "note": "Details should clearly specify the changes requested",
          "on_error": "Request missing details from customer"
        },
        {
          "id": "1.3",
          "action": "Request customer to share previous year policy copy",
          "required": "Yes (Mandatory)",
          "validation": "Verify previous year policy copy is received and legible",
          "note": "Document must be complete and readable",
          "on_error": "Request document again from customer"
        }
      ],
      "decisions": [
        {
          "when": "1.1 = false",
          "action": "Follow up with customer for written consent",
          "status": null
        },
        {
          "when": "1.2 = false",
          "action": "Request missing change details from customer",
          "status": null
        },
        {
          "when": "1.3 = false",
          "action": "Request previous year policy copy from customer",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_2",
          "status": null
        }
      ]
    },
    {
      "name": "Raise Endorsement Request with Insurer",
      "actor": "Advisor",
      "to": "Insurer",
      "trigger": "All required documents and consent received from customer",
      "sub_steps": [
        {
          "id": "2.1",
          "action": "Raise a ticket through the endorsement module",
          "required": "Yes (Mandatory)",
          "validation": "Confirm ticket is successfully created in the system",
          "note": "Use the endorsement module as per internal process",
          "on_error": "Retry ticket creation; escalate to IT if system issue persists"
        },
        {
          "id": "2.2",
          "action": "Submit the ticket and all collected documents to the insurer for endorsement",
          "required": "Yes (Mandatory)",
          "validation": "Verify submission confirmation from insurer/system",
          "note": "Attach all required documents to the ticket",
          "on_error": "Resubmit documents; follow up with insurer if not acknowledged"
        }
      ],
      "decisions": [
        {
          "when": "2.1 = false",
          "action": "Retry or escalate ticket creation",
          "status": null
        },
        {
          "when": "2.2 = false",
          "action": "Resubmit documents or follow up with insurer",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_3",
          "status": null
        }
      ]
    },
    {
      "name": "Communicate Endorsement TAT to Customer",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Endorsement request submitted to insurer",
      "sub_steps": [
        {
          "id": "3.1",
          "action": "Share standard endorsement TAT (7-10 working days) with customer",
          "required": "Yes (Mandatory)",
          "validation": "Confirm customer acknowledges receipt of TAT information",
          "note": "Standard TAT: 7-10 working days; clarify that actual TAT may vary",
          "on_error": "Resend TAT information; follow up for acknowledgment"
        }
      ],
      "decisions": [
        {
          "when": "3.1 = false",
          "action": "Resend TAT information to customer",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "Proceed to STEP_4",
          "status": null
        }
      ]
    },
    {
      "name": "Validate and Share Endorsed Documents; Close Ticket",
      "actor": "Advisor",
      "to": "Customer",
      "trigger": "Insurer shares Endorsed Letter or updated Policy Copy",
      "sub_steps": [
        {
          "id": "4.1",
          "action": "Validate the Endorsed Letter or updated Policy Copy received from insurer",
          "required": "Yes (Mandatory)",
          "validation": "Check document for accuracy and completeness of requested changes",
          "note": "If correction is needed post validation, only a request (not endorsement) should be raised with insurer",
          "on_error": "Contact insurer for correction or clarification"
        },
        {
          "id": "4.2",
          "action": "Share the validated Endorsed Letter or updated Policy Copy with customer",
          "required": "Yes (Mandatory)",
          "validation": "Confirm customer receives and acknowledges the document",
          "note": "Ensure customer understands the changes made",
          "on_error": "Resend document to customer; follow up for acknowledgment"
        },
        {
          "id": "4.3",
          "action": "Close the ticket in the system",
          "required": "Yes (Mandatory)",
          "validation": "Verify ticket status is updated to closed",
          "note": "Ensure all documentation is complete before closing",
          "on_error": "Retry ticket closure; escalate if system issue persists"
        }
      ],
      "decisions": [
        {
          "when": "4.1 = false",
          "action": "Raise correction request with insurer; do not proceed to share with customer",
          "status": null
        },
        {
          "when": "4.2 = false",
          "action": "Resend document to customer; follow up for acknowledgment",
          "status": null
        },
        {
          "when": "4.3 = false",
          "action": "Retry ticket closure or escalate to IT",
          "status": null
        },
        {
          "when": "All sub-steps complete",
          "action": "STATUS: COMPLETED",
          "status": "COMPLETED"
        }
      ]
    }
  ]
}

